def _guide_constraints(
    payload: Mapping[str, Any],
    *,
    mode: PerturbationMode,
    context_key: str,
    design_id: str | None,
    guide_length: int | None,
    max_guides: int | None,
    require_pam: bool,
    pam_pattern: str | None,
) -> GuideDesignConstraints:
    raw = dict(payload.get("constraints", {}))
    raw["context_key"] = context_key
    raw["mode"] = mode.value
    if design_id is not None:
        raw["design_id"] = design_id
    if guide_length is not None:
        raw["guide_length"] = guide_length
    if max_guides is not None:
        raw["max_guides"] = max_guides
    if require_pam:
        raw["require_pam"] = True
    if pam_pattern is not None:
        raw["pam_pattern"] = pam_pattern
    return GuideDesignConstraints.from_mapping(raw, context_key=context_key, mode=mode)


def _graph_from_payload(payload: Mapping[str, Any]):
    context_key = str(payload.get("context_key", ""))
    if not context_key:
        raise ValueError("graph input requires context_key")
    citations = tuple(
        EvidenceCitation.from_mapping(
            row,
            fallback_source_id=str(row.get("source_id", "declared_source")),
            fallback_version=str(row.get("version", "unspecified")),
            fallback_row_number=index,
        )
        for index, row in enumerate(payload.get("citations", ()), start=1)
    )
    claims = tuple(
        VersionedEvidenceClaim.from_mapping(
            row,
            fallback_id=f"graph-cli:{index}",
            context_key=context_key,
        )
        for index, row in enumerate(payload.get("claims", ()), start=1)
    )
    return VersionedEvidenceGraphConstructor().construct(
        claims,
        citations=citations,
        graph_id=str(payload.get("graph_id", "evidence-graph-cli")),
        context_key=context_key,
        graph_version=int(payload.get("graph_version", 1)),
    )


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="glio-noncode", description="Inspectable research hypothesis runtime"
    )
    subparsers = parser.add_subparsers(dest="command", required=True)

    evaluate = subparsers.add_parser("evaluate", help="evaluate a case manifest")
    evaluate.add_argument("manifest", type=str)
    evaluate.add_argument("--data-root", default=".glio")
    evaluate.add_argument("--output", default=None)
    evaluate.add_argument(
        "--live-reference",
        action="store_true",
        help="retrieve bounded sequence and annotation data from public APIs",
    )
    evaluate.add_argument(
        "--window-bp", default=2000, type=int, help="half-window for live reference retrieval"
    )

    evaluate_batch = subparsers.add_parser(
        "evaluate-batch",
        help="evaluate a manifest list with durable per-item results",
    )
    evaluate_batch.add_argument("input", type=str, help="JSON batch object or manifest list")
    evaluate_batch.add_argument("--data-root", default=".glio")
    evaluate_batch.add_argument("--output", default=None)
    evaluate_batch.add_argument("--live-reference", action="store_true")
    evaluate_batch.add_argument("--window-bp", default=2000, type=int)
    evaluate_batch.add_argument("--max-items", default=100, type=int)

    batch_inspect = subparsers.add_parser(
        "batch-inspect",
        help="reopen and verify one persisted batch result",
    )
    batch_inspect.add_argument("batch_id", type=str)
    batch_inspect.add_argument("--data-root", default=".glio")
    batch_inspect.add_argument("--output", default=None)

    batch_catalog = subparsers.add_parser(
        "batch-catalog",
        help="list persisted batch results",
    )
    batch_catalog.add_argument("--data-root", default=".glio")
    batch_catalog.add_argument("--offset", default=0, type=int)
    batch_catalog.add_argument("--limit", default=25, type=int)
    batch_catalog.add_argument("--text", default=None)
    batch_catalog.add_argument("--output", default=None)

    batch_release = subparsers.add_parser(
        "batch-release",
        help="build a gated portable release bundle for one persisted batch",
    )
    batch_release.add_argument("batch_id", type=str)
    batch_release.add_argument("--data-root", default=".glio")
    batch_release.add_argument("--output", required=True)

    batch_release_verify = subparsers.add_parser(
        "batch-release-verify",
        help="verify a previously written batch release bundle",
    )
    batch_release_verify.add_argument("input", type=str)
    batch_release_verify.add_argument("--output", default=None)

    run_search = subparsers.add_parser(
        "run-search",
        help="search public projections across replay-verified persisted runs",
    )
    run_search.add_argument("--data-root", default=".glio")
    run_search.add_argument("--query", "--text", dest="query", default=None)
    run_search.add_argument("--resource", choices=RUN_SEARCH_RESOURCES, default="all")
    run_search.add_argument("--case-id", default=None)
    run_search.add_argument("--status", default=None)
    run_search.add_argument("--reviewer", default=None)
    run_search.add_argument("--review-state", default=None)
    run_search.add_argument("--state", default=None)
    run_search.add_argument("--tier", default=None)
    run_search.add_argument("--channel", default=None)
    run_search.add_argument("--min-support", default=None, type=float)
    run_search.add_argument("--max-uncertainty", default=None, type=float)
    run_search.add_argument("--assay", default=None)
    run_search.add_argument("--accepted-only", action="store_true")
    run_search.add_argument("--offset", default=0, type=int)
    run_search.add_argument("--limit", default=RUN_SEARCH_DEFAULT_LIMIT, type=int)
    run_search.add_argument("--closure", action="store_true")
    run_search.add_argument("--output", default=None)

    fetch_public = subparsers.add_parser(
        "fetch-public", help="retrieve and emit live public reference data for a manifest"
    )
    fetch_public.add_argument("manifest", type=str)
    fetch_public.add_argument("--data-root", default=".glio")
    fetch_public.add_argument("--output", default=None)
    fetch_public.add_argument("--window-bp", default=2000, type=int)

    serve = subparsers.add_parser("serve", help="run the local JSON API")
    serve.add_argument("--host", default="127.0.0.1")
    serve.add_argument("--port", default=8765, type=int)
    serve.add_argument("--data-root", default=".glio")
    serve.add_argument("--deployment-profile", default=None)
    serve.add_argument("--api-key-file", default=None)
    serve.add_argument("--audit-root", default=None)
    serve.add_argument(
        "--audit-retention-limit",
        default=DEPLOYMENT_DEFAULT_AUDIT_RETENTION_LIMIT,
        type=int,
    )

    deployment_profile = subparsers.add_parser(
        "deployment-profile",
        help="emit an authenticated deployment profile without credential material",
    )
    deployment_profile.add_argument("--profile-id", default="glio-noncode-local")
    deployment_profile.add_argument("--host", default="127.0.0.1")
    deployment_profile.add_argument(
        "--exposure",
        choices=tuple(item.value for item in DeploymentExposure),
        default=None,
    )
    deployment_profile.add_argument(
        "--authentication",
        choices=tuple(item.value for item in DeploymentAuthentication),
        default=None,
    )
    deployment_profile.add_argument("--tls-required", action="store_true")
    deployment_profile.add_argument("--audit-disabled", action="store_true")
